   694→void UWjWorldCurrencySubsystem::PollExchangeResult()
   695→{
   696→#if WITH_STEAM
   697→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   698→	{
   699→		StopExchangePolling();
   700→		return;
   701→	}
   702→
   703→	ISteamInventory* SteamInv = SteamInventory();
   704→	if (!SteamInv)
   705→	{
   706→		StopExchangePolling();
   707→		bExchangePending = false;
   708→		if (bPendingIsPlacement)
   709→		{
   710→			OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   711→		}
   712→		else
   713→		{
   714→			OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   715→		}
   716→		bPendingIsPlacement = false;
   717→		PendingExchangeItemId = NAME_None;
   718→		return;
   719→	}
   720→
   721→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   722→	if (Status == k_EResultPending)
   723→	{
   724→		return;
   725→	}
   726→
   727→	bool bSuccess = (Status == k_EResultOK);
   728→	if (bSuccess)
   729→	{
   730→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   731→
   732→		// 인벤토리 갱신
   733→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   734→		if (CosmeticSub)
   735→		{
   736→			CosmeticSub->RequestInventoryRefresh();
   737→		}
   738→	}
   739→	else
   740→	{
   741→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   742→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   743→	}
   744→
   745→	SteamInv->DestroyResult(ExchangeResultHandle);
   746→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   747→
   748→	bExchangePending = false;
   749→
   750→	// 배치 vs 코스메틱 분기
   751→	if (bPendingIsPlacement)
   752→	{
   753→		OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   754→	}
   755→	else
   756→	{
   757→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   758→	}
   759→	bPendingIsPlacement = false;
   760→	PendingExchangeItemId = NAME_None;
   761→
   762→	StopExchangePolling();
   763→#else
   764→	StopExchangePolling();
   765→#endif
   766→}
   767→
   768→void UWjWorldCurrencySubsystem::StartExchangePolling()
   769→{
   770→	UWorld* World = GetWorld();
   771→	if (!World)
   772→	{
   773→		return;
   774→	}
   775→
   776→	World->GetTimerManager().SetTimer(
   777→		ExchangePollTimerHandle,
   778→		this,
   779→		&UWjWorldCurrencySubsystem::PollExchangeResult,
   780→		0.5f,
   781→		true
   782→	);
   783→}
