   880→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   881→{
   882→	NewAmount = FMath::Max(0, NewAmount);
   883→
   884→	switch (Type)
   885→	{
   886→	case ECurrencyType::Coin:
   887→		if (CoinBalance != NewAmount)
   888→		{
   889→			CoinBalance = NewAmount;
   890→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   891→		}
   892→		break;
   893→	case ECurrencyType::Gem:
   894→		if (GemBalance != NewAmount)
   895→		{
   896→			GemBalance = NewAmount;
