	void SaveDailyRewardData();

	/** 날짜 변경 시 카운트 리셋 */
	void CheckDailyReset();

	/** 인벤토리 갱신 지연 호출 (2.5초 + 5초 재시도) */
	void ScheduleInventoryRefresh();
};

