	int32 CurrentGemBalance = CurrencySub ? CurrencySub->GetBalance(ECurrencyType::Gem) : 0;

	for (UGemCoinExchangeEntryWidget* Entry : ExchangeEntryWidgets)
	{
		if (Entry)
		{
			Entry->UpdateButtonState(CurrentGemBalance);
		}
	}
}

