    19→			CachedGemBalance = CurrencySub->GetBalance(ECurrencyType::Gem);
    20→
    21→			CurrencySub->OnCurrencyBalanceChanged.RemoveDynamic(this, &UCoinGainNotificationWidget::OnCurrencyBalanceChanged);
    22→			CurrencySub->OnCurrencyBalanceChanged.AddDynamic(this, &UCoinGainNotificationWidget::OnCurrencyBalanceChanged);
