    52→void UCoinGainNotificationWidget::OnCurrencyBalanceChanged(ECurrencyType CurrencyType, int32 NewBalance)
    53→{
    54→	int32 Delta = 0;
    55→
    56→	switch (CurrencyType)
    57→	{
    58→	case ECurrencyType::Coin:
    59→		Delta = NewBalance - CachedCoinBalance;
    60→		CachedCoinBalance = NewBalance;
    61→		break;
    62→	case ECurrencyType::Gem:
    63→		Delta = NewBalance - CachedGemBalance;
    64→		CachedGemBalance = NewBalance;
    65→		break;
    66→	}
    67→
    68→	if (Delta > 0)
    69→	{
    70→		FString CurrencyName = (CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem");
    71→		ShowNotification(FString::Printf(TEXT("+%d %s"), Delta, *CurrencyName));
    72→	}
    73→}
