    79→		return;
    80→	}
    81→
    82→	NotificationText->SetText(FText::FromString(Message));
    83→	NotificationText->SetColorAndOpacity(FSlateColor(FLinearColor(1.0f, 0.85f, 0.0f, 1.0f))); // 금색
    84→	NotificationText->SetVisibility(ESlateVisibility::HitTestInvisible);
    85→
    86→	UE_LOG(LogWjWorldCurrency, Log, TEXT("CoinGainNotification: %s"), *Message);
    87→
    88→	// 기존 타이머 리셋 후 새로 시작
    89→	if (UWorld* World = GetWorld())
    90→	{
    91→		World->GetTimerManager().ClearTimer(HideTimerHandle);
    92→		World->GetTimerManager().SetTimer(
    93→			HideTimerHandle,
    94→			this,
    95→			&UCoinGainNotificationWidget::HideNotification,
    96→			DisplayDuration,
    97→			false
    98→		);
    99→	}
