   430→bool UWjWorldCurrencySubsystem::ExchangeGemsForCoins(int32 ExchangeDefId)
   431→{
   432→	if (bExchangePending)
   433→	{
   434→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   435→		return false;
   436→	}
   437→
   438→	// DeveloperSettings에서 교환 정의 조회
   439→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   440→	if (!Settings)
   441→	{
   442→		return false;
   443→	}
   444→
   445→	const FGemCoinExchangeDefinition* ExchangeDef = nullptr;
   446→	for (const FGemCoinExchangeDefinition& Def : Settings->GemCoinExchangeDefinitions)
   447→	{
   448→		if (Def.SteamItemDefId == ExchangeDefId)
   449→		{
   450→			ExchangeDef = &Def;
   451→			break;
   452→		}
   453→	}
   454→
   455→	if (!ExchangeDef)
   456→	{
   457→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("교환 정의를 찾을 수 없음 (DefId: %d)"), ExchangeDefId);
   458→		return false;
   459→	}
   460→
   461→	if (ExchangeDef->GemCost <= 0 || ExchangeDef->CoinAmount <= 0)
   462→	{
   463→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 교환 정의 (GemCost: %d, CoinAmount: %d)"),
   464→			ExchangeDef->GemCost, ExchangeDef->CoinAmount);
   465→		return false;
   466→	}
   467→
   468→	// Gem 잔액 확인
   469→	if (GemBalance < ExchangeDef->GemCost)
   470→	{
   471→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 잔액 부족: %d < %d"), GemBalance, ExchangeDef->GemCost);
   472→		return false;
   473→	}
   474→
   475→	UE_LOG(LogWjWorldCurrency, Log, TEXT("Gem→Coin 교환 요청: DefId=%d (%d Gem → %d Coin)"),
   476→		ExchangeDefId, ExchangeDef->GemCost, ExchangeDef->CoinAmount);
   477→
   478→#if WITH_STEAM
   479→	ISteamInventory* SteamInv = SteamInventory();
   480→	if (SteamInv)
   481→	{
   482→		if (CachedGemInstanceId == k_SteamItemInstanceIDInvalid)
   483→		{
   484→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   485→			return false;
   486→		}
   487→
   488→		// 기존 핸들 정리
   489→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   490→		{
   491→			SteamInv->DestroyResult(ExchangeResultHandle);
   492→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   493→		}
   494→
   495→		// ExchangeItems: Gem 소비 → bundle(DefId 60~62) 획득 → 자동으로 Coin 지급
   496→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(ExchangeDefId);
   497→		uint32 OutputQuantity = 1;
